def cached_total(cache, snapshots, version, left, right, scale):
    values = snapshots[version]
    if not 0 <= left <= right <= len(values):
        raise ValueError("invalid range")
    key = ("sum-v1", version, left, right, scale)
    if key not in cache:
        cache[key] = sum(values[left:right]) * scale
    return cache[key]

snapshots = {"v1": (2, 5, 1), "v2": (2, 9, 1)}
cache = {}
print(cached_total(cache, snapshots, "v1", 0, 3, 1))
print(cached_total(cache, snapshots, "v1", 0, 3, 1))
print(len(cache))
print(cached_total(cache, snapshots, "v1", 0, 3, 2))
print(cached_total(cache, snapshots, "v2", 0, 3, 1))
print(len(cache))

def square_cached(cache, value):
    if value in cache:
        return cache[value], True
    result = value * value
    cache[value] = result
    return result, False

cache = {}
print(square_cached(cache, 0))
print(square_cached(cache, 0))
print(square_cached(cache, -3))

def cached_range_total(cache, snapshots, version, left, right, scale):
    values = snapshots[version]
    if not 0 <= left <= right <= len(values):
        raise ValueError('invalid range')
    key = ('sum-v1', version, left, right, scale)
    if key not in cache:
        cache[key] = sum(values[left:right]) * scale
    return cache[key]

snapshots = {'v1': (2, 5, 1), 'v2': (2, 9, 1)}
cache = {}
print(cached_range_total(cache, snapshots, 'v1', 0, 3, 1))
print(cached_range_total(cache, snapshots, 'v1', 0, 3, 2))
print(cached_range_total(cache, snapshots, 'v2', 0, 3, 1))
print(cached_range_total(cache, snapshots, 'v2', 1, 1, 1))

def read_ttl(cache, key, now):
    if key not in cache:
        return False, None
    expires, value = cache[key]
    if now >= expires:
        del cache[key]
        return False, None
    return True, value

cache = {'A': (10, 0), 'N': (12, None)}
print(read_ttl(cache, 'A', 9))
print(read_ttl(cache, 'A', 10))
print(read_ttl(cache, 'N', 10))
print(read_ttl(cache, 'M', 10))

def cached_ids(cache, key, compute):
    if key not in cache:
        cache[key] = tuple(compute())
    return list(cache[key])

calls = []
def make_ids():
    calls.append('ids')
    return [2, 5]
def make_empty():
    calls.append('empty')
    return []

cache = {}
first = cached_ids(cache, ('v1', 'ids'), make_ids)
print(first)
first.append(99)
print(cached_ids(cache, ('v1', 'ids'), make_ids))
print(cached_ids(cache, ('v1', 'empty'), make_empty))
print(len(calls))
